import { activateCard, advanceGame, createGame, isWon } from '../game.ts';
import { parseBoardCode } from '../deck.ts';
import type { GameState } from '../game.ts';

export type PlayerCount = 4 | 8;
export type RoundName = 'Quarterfinal' | 'Semifinal' | 'Final';
export interface TournamentPlayer {
  readonly name: string;
  readonly seed: number;
}
export interface MatchResult {
  readonly elapsedMs: number;
  readonly moves: number;
  readonly playerSeed: number;
}
export type MatchPlayers = readonly [number | null, number | null];
export type MatchResults = readonly [MatchResult | null, MatchResult | null];
export interface TournamentMatch {
  readonly boardCode: string;
  readonly players: MatchPlayers;
  readonly results: MatchResults;
  readonly winnerSeed: number | null;
}
export interface TournamentRound {
  readonly matches: readonly TournamentMatch[];
  readonly name: RoundName;
  readonly size: number;
}
export interface TournamentRecord {
  readonly playerCount: PlayerCount;
  readonly players: readonly TournamentPlayer[];
  readonly rounds: readonly TournamentRound[];
}
export interface TournamentState extends TournamentRecord {
  readonly currentGame: GameState | null;
  readonly currentMatch: number;
  readonly currentRound: number;
  readonly currentTurn: 0 | 1;
  readonly status: 'playing' | 'complete';
}

const OPENING: Record<PlayerCount, readonly (readonly [number, number])[]> = {
  4: [[1, 4], [2, 3]],
  8: [[1, 8], [4, 5], [3, 6], [2, 7]],
};

export function roundSizes(count: PlayerCount): readonly number[] {
  return count === 4 ? [6, 8] : [4, 6, 8];
}

export function roundName(count: PlayerCount, index: number): RoundName {
  return (count === 4 ? ['Semifinal', 'Final'] : ['Quarterfinal', 'Semifinal', 'Final'])[
    index
  ] ?? 'Final';
}

export function createTournament(names: readonly string[], codes: readonly string[]): TournamentState | null {
  if (names.length !== 4 && names.length !== 8) return null;
  const playerCount = names.length as PlayerCount;
  const sizes = roundSizes(playerCount);
  const matchCounts = sizes.map((_, index) => playerCount / 2 ** (index + 1));
  if (codes.length !== matchCounts.reduce((sum, count) => sum + count, 0)) return null;
  const used = new Set<string>();
  let codeIndex = 0;
  const rounds = sizes.map((size, roundIndex) => {
    const count = matchCounts[roundIndex] ?? 0;
    const matches = Array.from({ length: count }, (_, index) => {
      const code = codes[codeIndex++];
      const parsed = code ? parseBoardCode(code) : null;
      if (!code || !parsed || parsed.size !== size || used.has(code)) return null;
      used.add(code);
      const players: MatchPlayers = roundIndex === 0
        ? (OPENING[playerCount][index] ?? [1, 1])
        : [null, null];
      return { boardCode: code, players, results: [null, null] as const, winnerSeed: null };
    });
    if (matches.some((match) => match === null)) return null;
    return {
      matches: matches.filter((match): match is TournamentMatch => match !== null),
      name: roundName(playerCount, roundIndex),
      size,
    };
  });
  if (rounds.some((round) => round === null)) return null;
  return {
    playerCount,
    players: names.map((name, index) => ({ name, seed: index + 1 })),
    rounds: rounds.filter((round): round is TournamentRound => round !== null),
    currentRound: 0,
    currentMatch: 0,
    currentTurn: 0,
    currentGame: null,
    status: 'playing',
  };
}

export function currentMatch(state: TournamentState): TournamentMatch {
  return state.rounds[state.currentRound]?.matches[state.currentMatch] ?? state.rounds[0]!.matches[0]!;
}

export function currentPlayer(state: TournamentState): TournamentPlayer | null {
  const seed = currentMatch(state).players[state.currentTurn];
  return seed === null ? null : state.players[seed - 1] ?? null;
}

export function championSeed(state: TournamentState): number | null {
  return state.status === 'complete'
    ? state.rounds.at(-1)?.matches[0]?.winnerSeed ?? null
    : null;
}

export function startTurn(state: TournamentState): TournamentState {
  const match = currentMatch(state);
  if (state.status !== 'playing' || state.currentGame || match.results[state.currentTurn]) return state;
  return { ...state, currentGame: createGame(match.boardCode) };
}

export function advanceTournament(state: TournamentState, milliseconds: number): TournamentState {
  if (!state.currentGame || state.status !== 'playing') return state;
  const game = advanceGame(state.currentGame, milliseconds);
  return game === state.currentGame ? state : { ...state, currentGame: game };
}

export function activateTournament(state: TournamentState, index: number): TournamentState {
  if (!state.currentGame || state.status !== 'playing' || isWon(state.currentGame)) return state;
  const game = activateCard(state.currentGame, index);
  if (game === state.currentGame) return state;
  const updated = { ...state, currentGame: game };
  if (!isWon(game)) return updated;
  const seed = currentMatch(state).players[state.currentTurn];
  if (seed === null) return state;
  const result = { elapsedMs: game.elapsedMs, moves: game.moves, playerSeed: seed };
  return recordResult(updated, result);
}

function recordResult(state: TournamentState, result: MatchResult): TournamentState {
  const match = currentMatch(state);
  const results: MatchResults = state.currentTurn === 0
    ? [result, match.results[1]]
    : [match.results[0], result];
  const winner = results[0] && results[1] ? compareResults(results[0], results[1]) : null;
  const replacement = { ...match, results, winnerSeed: winner };
  let rounds = replaceMatch(state.rounds, state.currentRound, state.currentMatch, replacement);
  if (winner !== null && state.currentRound + 1 < rounds.length) {
    const nextIndex = Math.floor(state.currentMatch / 2);
    const slot = state.currentMatch % 2;
    const nextRound = rounds[state.currentRound + 1]!;
    const nextMatch = nextRound.matches[nextIndex]!;
    const players: MatchPlayers = slot === 0
      ? [winner, nextMatch.players[1]]
      : [nextMatch.players[0], winner];
    rounds = replaceMatch(rounds, state.currentRound + 1, nextIndex, { ...nextMatch, players });
  }
  return { ...state, rounds };
}

function replaceMatch(
  rounds: readonly TournamentRound[], roundIndex: number, matchIndex: number, match: TournamentMatch,
): readonly TournamentRound[] {
  return rounds.map((round, index) => index !== roundIndex ? round : {
    ...round,
    matches: round.matches.map((item, itemIndex) => itemIndex === matchIndex ? match : item),
  });
}

function compareResults(first: MatchResult, second: MatchResult): number {
  if (first.moves !== second.moves) return first.moves < second.moves ? first.playerSeed : second.playerSeed;
  if (first.elapsedMs !== second.elapsedMs)
    return first.elapsedMs < second.elapsedMs ? first.playerSeed : second.playerSeed;
