      currentTurn: value.currentTurn,
      status: value.status,
    },
  };
}

export function readTournamentRecord(value: unknown): TournamentRecord | null {
  if (!isJsonObject(value) || !hasExactKeys(value, RECORD_KEYS)) return null;
  if (value.playerCount !== 4 && value.playerCount !== 8) return null;
  const record = readRecordValues(value.playerCount, value.players, value.rounds, true);
  return record && record.rounds.at(-1)?.matches[0]?.winnerSeed ? record : null;
}

function readSetup(value: Record<string, unknown>, count: PlayerCount): TournamentLoad | null {
  const players = readPlayers(value.players, count, false);
  if (
    !players || !Array.isArray(value.rounds) || value.rounds.length !== 0 ||
    value.currentGame !== null || value.currentRound !== 0 || value.currentMatch !== 0 ||
    value.currentTurn !== 0
  ) return null;
  return { kind: 'setup', draft: { playerCount: count, names: players.map((player) => player.name) } };
}

function readRecordValues(
  countValue: unknown, playersValue: unknown, roundsValue: unknown, requireComplete: boolean,
): TournamentRecord | null {
  if (countValue !== 4 && countValue !== 8) return null;
  const count: PlayerCount = countValue;
  const players = readPlayers(playersValue, count, true);
  const rounds = readRounds(roundsValue, count, requireComplete);
  if (!players || !rounds) return null;
  const names = players.map((player) => player.name);
  const normalized = validateNames(names, count);
  if (normalized.error || names.some((name, index) => name !== normalizeName(name))) return null;
  return { playerCount: count, players, rounds };
}

function readPlayers(
  value: unknown, count: PlayerCount, requireNames: boolean,
): readonly TournamentPlayer[] | null {
  if (!Array.isArray(value) || value.length !== count) return null;
  const players: TournamentPlayer[] = [];
  for (let index = 0; index < count; index += 1) {
    const player = value[index];
    if (
      !isJsonObject(player) || !hasExactKeys(player, PLAYER_KEYS) ||
      typeof player.name !== 'string' || player.seed !== index + 1
    ) return null;
    if (requireNames && player.name !== normalizeName(player.name)) return null;
    players.push({ name: player.name, seed: player.seed });
  }
  return players;
}

function validateProgress(
  rounds: readonly TournamentRound[], currentRound: number, currentMatch: number,
): boolean {
  return rounds.every((round, roundIndex) => round.matches.every((match, matchIndex) => {
    const complete = match.winnerSeed !== null && match.results[0] !== null && match.results[1] !== null;
    const untouched = match.winnerSeed === null && match.results[0] === null && match.results[1] === null;
    if (roundIndex < currentRound) return complete;
    if (roundIndex > currentRound) return untouched;
    if (matchIndex < currentMatch) return complete;
    if (matchIndex > currentMatch) return untouched;
    return true;
  }));
}

function validCurrentTurn(
  results: TournamentState['rounds'][number]['matches'][number]['results'],
  turn: 0 | 1,
  game: TournamentState['currentGame'],
): boolean {
  const result = results[turn];
  if (turn === 0 && results[1]) return false;
  if (turn === 1 && !results[0]) return false;
  if (!game) return result === null;
  const won = isWon(game);
  if (result === null) return !won;
  return won && result.moves === game.moves && Math.floor(result.elapsedMs) === game.elapsedMs;
}

