import { useEffect, useRef } from 'react';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { currentMatch, currentPlayer } from './rules.ts';
import { championSeed } from './rules.ts';
import { TournamentBracket } from './TournamentBracket.tsx';
import { TournamentStatus } from './TournamentStatus.tsx';
import type { TournamentState } from './rules.ts';
import './tournament.css';

interface TournamentPlayProps {
  tournament: TournamentState;
  activate(index: number): void;
  startTurn(): void;
  nextTurn(): void;
  nextMatch(): void;
  back(): void;
  leave(): void;
}

export function TournamentPlay({ tournament, activate, startTurn, nextTurn, nextMatch, back, leave }: TournamentPlayProps) {
  const board = useRef<BoardFocus>(null);
  const hasGame = Boolean(tournament.currentGame);
  const previousHasGame = useRef(false);
  const match = currentMatch(tournament);
  const player = currentPlayer(tournament);
  const champion = championSeed(tournament);

  useEffect(() => {
    if (hasGame && !previousHasGame.current) board.current?.focusRemembered();
    previousHasGame.current = hasGame;
  }, [hasGame]);

  const action = tournament.status === 'complete'
    ? { label: 'Back to game', run: back }
    : match.results[0] && !match.results[1]
      ? tournament.currentTurn === 0
        ? { label: 'Next turn', run: nextTurn }
        : { label: 'Start turn', run: startTurn }
      : match.winnerSeed !== null
        ? { label: 'Next match', run: nextMatch }
        : !tournament.currentGame
          ? { label: 'Start turn', run: startTurn }
          : null;

  return (
    <section className="tournament-play" aria-labelledby="tournament-round-title">
      {tournament.status === 'complete' ? (
        <>
          <p className="champion">Champion: {tournament.players.find((entry) => entry.seed === champion)?.name}</p>
          <TournamentBracket record={tournament} />
          <button className="control" type="button" onClick={back}>Back to game</button>
        </>
      ) : (
        <>
          <h3 id="tournament-round-title">Round: {tournament.rounds[tournament.currentRound]?.name}</h3>
          <p className="tournament-match-label">Match {tournament.currentMatch + 1} of {tournament.rounds[tournament.currentRound]?.matches.length}</p>
          <p className="now-playing">Now playing: {player?.name}</p>
          {tournament.currentGame && (
            <>
              <TournamentStatus game={tournament.currentGame} />
              <p id="tournament-board-help" className="help">
                Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space reveals a card.
              </p>
              <Board
                key={`${tournament.currentRound}-${tournament.currentMatch}-${tournament.currentTurn}`}
                game={tournament.currentGame}
                activate={activate}
                ref={board}
              />
            </>
          )}
          <div className="tournament-actions">
            {action && <button className="control" type="button" onClick={action.run}>{action.label}</button>}
            <button className="control" type="button" onClick={leave}>Leave tournament</button>
          </div>
          <TournamentBracket record={tournament} />
        </>
      )}
    </section>
  );
}

