import { useEffect, useRef, useState } from 'react';
import type { SyntheticEvent } from 'react';
import { TournamentHistory } from './TournamentHistory.tsx';
import { TournamentExchange } from './TournamentExchange.tsx';
import { TournamentPlay } from './TournamentPlay.tsx';
import { TournamentSetup } from './TournamentSetup.tsx';
import { useTournament } from '../session/use-tournament.ts';
import { validateNames } from './names.ts';
import { currentMatch, currentPlayer } from './bracket.ts';
import type { TournamentLoad } from './format-read.ts';
import './tournament.css';

interface TournamentProps {
  backToGame(): void;
}

const emptyNames = () => Array.from({ length: 8 }, () => '');

export function Tournament({ backToGame }: TournamentProps) {
  const controller = useTournament();
  const heading = useRef<HTMLHeadingElement>(null);
  const dialog = useRef<HTMLDialogElement>(null);
  const keepPlaying = useRef<HTMLButtonElement>(null);
  const [playerCount, setPlayerCount] = useState<4 | 8>(4);
  const [names, setNames] = useState<string[]>(emptyNames);
  const [json, setJson] = useState('');
  const [setupMessage, setSetupMessage] = useState('');
  const [exchangeMessage, setExchangeMessage] = useState('');
  const [pending, setPending] = useState<TournamentLoad | 'leave' | null>(null);
  const [playGeneration, setPlayGeneration] = useState(0);
  const [announcement, setAnnouncement] = useState('');
  const [announcementId, setAnnouncementId] = useState(0);
  const lastAnnouncementKey = useRef('');

  function announce(message: string): void {
    setAnnouncement(message);
    setAnnouncementId((value) => value + 1);
  }

  useEffect(() => {
    const state = controller.tournament;
    if (!state) {
      lastAnnouncementKey.current = '';
      return;
    }
    const match = currentMatch(state);
    const resultKey = match.results.map((result) => result ? `${result.moves}/${result.elapsedMs}` : '-').join(':');
    const key = `${playGeneration}:${state.status}:${state.currentRound}:${state.currentMatch}:${state.currentTurn}:${match.boardCode}:${resultKey}:${match.winnerSeed}`;
    if (key === lastAnnouncementKey.current) return;
    lastAnnouncementKey.current = key;
    if (state.status === 'complete') return;
    const player = currentPlayer(state);
    const winner = state.players.find((entry) => entry.seed === match.winnerSeed);
    const result = match.results[state.currentTurn];
    const message = match.winnerSeed !== null ? `Match complete. ${winner?.name} wins.`
      : result ? `${player?.name} finished in ${result.moves} moves. Select Next turn when ready.`
        : `Now playing: ${player?.name}`;
    announce(message);
  }, [controller.tournament, playGeneration]);

  useEffect(() => { heading.current?.focus(); }, []);
  useEffect(() => {
    if (!pending || !dialog.current) return;
    if (!dialog.current.open) dialog.current.showModal();
    keepPlaying.current?.focus();
  }, [pending]);

  function changeName(index: number, name: string): void {
    setNames((values) => values.map((value, position) => position === index ? name : value));
  }

  function start(): void {
    const checked = validateNames(names, playerCount);
    setSetupMessage(checked.error);
    if (checked.error) {
      announce(checked.error);
      return;
    }
    if (controller.start(checked.names, playerCount)) {
      setNames((values) => values.map((value, index) => checked.names[index] ?? value));
      setSetupMessage('');
      setExchangeMessage('');
    }
  }

  function exportTournament(): void {
    setJson(controller.exportCurrent({ names, playerCount }));
  }

  function restore(value: TournamentLoad): void {
    setPlayGeneration((generation) => generation + 1);
    setSetupMessage('');
    setPlayerCount(value.kind === 'setup' ? value.draft.playerCount : value.state.playerCount);
    setNames(value.kind === 'setup'
      ? [...value.draft.names, ...emptyNames()].slice(0, 8)
      : [...value.state.players.map((player) => player.name), ...emptyNames()].slice(0, 8));
    controller.restore(value);
    setExchangeMessage('Tournament loaded.');
    announce('Tournament loaded.');
  }

  function loadTournament(): void {
    const loaded = controller.decode(json);
    if (!loaded) {
      setExchangeMessage('Invalid tournament.');
      announce('Invalid tournament.');
      return;
    }
    if (controller.tournament?.status === 'playing') setPending(loaded);
    else restore(loaded);
  }

  function closeDecision(): void {
    if (dialog.current?.open) dialog.current.close();
    setPending(null);
  }

  function confirmDecision(): void {
    const selected = pending;
    closeDecision();
    if (selected === 'leave') {
      controller.leave();
      backToGame();
    } else if (selected) restore(selected);
  }

  function cancelDecision(event?: SyntheticEvent<HTMLDialogElement>): void {
    event?.preventDefault();
    closeDecision();
  }

  return (
    <section className="tournament-screen" aria-labelledby="tournament-title">
      <h2 id="tournament-title" ref={heading} tabIndex={-1}>Tournament</h2>
      <p className="tournament-live" role="status" aria-live="polite" aria-atomic="true">
        <span key={announcementId}>{announcement}</span>
      </p>
      {!controller.tournament ? (
        <TournamentSetup
          count={playerCount}
          names={names}
          changeCount={setPlayerCount}
          changeName={changeName}
          start={start}
          back={backToGame}
          message={setupMessage}
        />
      ) : (
        <TournamentPlay
          key={playGeneration}
          tournament={controller.tournament}
          activate={controller.activate}
          startTurn={controller.beginTurn}
          nextTurn={controller.continueTurn}
          nextMatch={controller.continueMatch}
          back={backToGame}
          leave={() => setPending('leave')}
        />
      )}
      <TournamentHistory items={controller.past} available={controller.storageAvailable} />
      <TournamentExchange
        value={json}
        change={setJson}
        exportTournament={exportTournament}
        loadTournament={loadTournament}
        notice={exchangeMessage}
      />
      <dialog
        ref={dialog}
        aria-labelledby="tournament-confirm-title"
        onCancel={cancelDecision}
      >
        <h3 id="tournament-confirm-title">
          {pending === 'leave' ? 'Leave tournament?' : 'Load this tournament?'}
        </h3>
        <p>{pending === 'leave' ? 'Current tournament progress will be discarded.' : 'Current tournament progress will be replaced.'}</p>
        <div className="tournament-actions">
          <button ref={keepPlaying} className="control" type="button" onClick={() => cancelDecision()}>
            {pending === 'leave' ? 'Keep playing' : 'Keep tournament'}
          </button>
          <button className="control" type="button" onClick={confirmDecision}>
            {pending === 'leave' ? 'Leave' : 'Load tournament'}
          </button>
        </div>
      </dialog>
    </section>
  );
}
import { useEffect, useRef } from 'react';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { championSeed, currentMatch, currentPlayer } from './bracket.ts';
import { TournamentBracket } from './TournamentBracket.tsx';
import { TournamentStatus } from './TournamentStatus.tsx';
import type { TournamentState } from './model.ts';
import './tournament.css';

interface TournamentPlayProps {
  tournament: TournamentState;
  activate(index: number): void;
  startTurn(): void;
  nextTurn(): void;
  nextMatch(): void;
  back(): void;
  leave(): void;
}

export function TournamentPlay({ tournament, activate, startTurn, nextTurn, nextMatch, back, leave }: TournamentPlayProps) {
  const board = useRef<BoardFocus>(null);
  const roundHeading = useRef<HTMLHeadingElement>(null);
  const championHeading = useRef<HTMLHeadingElement>(null);
  const hasGame = Boolean(tournament.currentGame);
  const previousHasGame = useRef(hasGame);
  const match = currentMatch(tournament);
  const player = currentPlayer(tournament);
  const champion = championSeed(tournament);

  useEffect(() => {
    if (hasGame && !previousHasGame.current) board.current?.focusRemembered();
    previousHasGame.current = hasGame;
  }, [hasGame]);
  useEffect(() => {
    if (tournament.status === 'complete') championHeading.current?.focus();
    else roundHeading.current?.focus();
  }, [tournament.status]);

  const action = tournament.status === 'complete'
    ? { label: 'Back to game', run: back }
    : match.results[0] && !match.results[1]
      ? tournament.currentTurn === 0
        ? { label: 'Next turn', run: nextTurn }
        : { label: 'Start turn', run: startTurn }
      : match.winnerSeed !== null
        ? { label: 'Next match', run: nextMatch }
        : !tournament.currentGame
          ? { label: 'Start turn', run: startTurn }
          : null;

  return (
    <section className="tournament-play" aria-labelledby="tournament-round-title">
      {tournament.status === 'complete' ? (
        <>
          <h3 id="tournament-round-title" ref={championHeading} className="champion" tabIndex={-1}>
            Champion: {tournament.players.find((entry) => entry.seed === champion)?.name}
          </h3>
          <TournamentBracket record={tournament} />
          <button className="control" type="button" onClick={back}>Back to game</button>
        </>
      ) : (
        <>
          <h3 id="tournament-round-title" ref={roundHeading} tabIndex={-1}>
            Round: {tournament.rounds[tournament.currentRound]?.name}
          </h3>
          <p className="tournament-match-label">Match {tournament.currentMatch + 1} of {tournament.rounds[tournament.currentRound]?.matches.length}</p>
          <p className="now-playing">Now playing: {player?.name}</p>
          {tournament.currentGame && (
            <>
              <TournamentStatus game={tournament.currentGame} />
              <p id="tournament-board-help" className="help">
                Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space reveals a card.
              </p>
              <Board
                key={`${tournament.currentRound}-${tournament.currentMatch}-${tournament.currentTurn}`}
                game={tournament.currentGame}
                activate={activate}
                helpId="tournament-board-help"
                ref={board}
              />
            </>
          )}
          <div className="tournament-actions">
            {action && <button className="control" type="button" onClick={action.run}>{action.label}</button>}
            <button className="control" type="button" onClick={leave}>Leave tournament</button>
          </div>
          <TournamentBracket record={tournament} />
        </>
      )}
    </section>
  );
}

