          changeCount={setPlayerCount}
          changeName={changeName}
          start={start}
          back={backToGame}
          message={setupMessage}
        />
      ) : (
        <TournamentPlay
          key={playGeneration}
          tournament={controller.tournament}
          activate={controller.activate}
          startTurn={controller.beginTurn}
          nextTurn={controller.continueTurn}
          nextMatch={controller.continueMatch}
          back={backToGame}
          leave={() => setPending('leave')}
        />
      )}
      <TournamentHistory items={controller.past} available={controller.storageAvailable} />
      <TournamentExchange
        value={json}
        change={setJson}
        exportTournament={exportTournament}
        loadTournament={loadTournament}
        notice={exchangeMessage}
      />
      <dialog ref={dialog} aria-labelledby="tournament-confirm-title" onCancel={cancelDecision}>
        <h3 id="tournament-confirm-title">
          {pending === 'leave' ? 'Leave tournament?' : 'Load this tournament?'}
        </h3>
        <p>
          {pending === 'leave'
            ? 'Current tournament progress will be discarded.'
            : 'Current tournament progress will be replaced.'}
        </p>
        <div className="tournament-actions">
          <button
            ref={keepPlaying}
            className="control"
            type="button"
            onClick={() => cancelDecision()}
          >
            {pending === 'leave' ? 'Keep playing' : 'Keep tournament'}
          </button>
          <button className="control" type="button" onClick={confirmDecision}>
            {pending === 'leave' ? 'Leave' : 'Load tournament'}
          </button>
        </div>
      </dialog>
    </section>
  );
}

