}

function replaceMatch(
  rounds: readonly TournamentRound[],
  roundIndex: number,
  matchIndex: number,
  match: TournamentMatch,
): readonly TournamentRound[] {
  return rounds.map((round, index) =>
    index !== roundIndex
      ? round
      : {
          ...round,
          matches: round.matches.map((item, itemIndex) =>
            itemIndex === matchIndex ? match : item,
          ),
        },
