import { SelectionKind } from '../selection.ts';
import type { GameState } from '../game.ts';
import type { Selection } from '../selection.ts';
import type { TournamentState } from './model.ts';

export const TOURNAMENT_FORMAT = 'neon-pairs/tournament';
export const TOURNAMENT_VERSION = 1;
export const TOURNAMENT_MAX_BYTES = 65_536;

export interface TournamentDraft {
  readonly names: readonly string[];
  readonly playerCount: 4 | 8;
}

function gameValue(game: GameState) {
  const selection: Selection = game.selection;
  const savedSelection =
    selection.kind === SelectionKind.mismatch
      ? {
          first: selection.first,
          kind: selection.kind,
          remainingMs: Math.ceil(selection.remainingMs),
          second: selection.second,
        }
      : selection.kind === SelectionKind.one
        ? { index: selection.index, kind: selection.kind }
        : { kind: selection.kind };
  return {
    boardCode: game.boardCode,
    elapsedMs: Math.floor(game.elapsedMs),
    matched: [...game.matched].sort((left, right) => left - right),
    moves: game.moves,
    selection: savedSelection,
    started: game.started,
  };
}

function roundValues(state: TournamentState) {
  return state.rounds.map((round) => ({
    matches: round.matches.map((match) => ({
      boardCode: match.boardCode,
      players: match.players,
      results: match.results.map(
        (result) =>
          result && {
            elapsedMs: result.elapsedMs,
            moves: result.moves,
            playerSeed: result.playerSeed,
          },
      ),
      winnerSeed: match.winnerSeed,
    })),
    name: round.name,
    size: round.size,
  }));
}

export function encodeTournament(state: TournamentState | null, draft: TournamentDraft): string {
  const players =
    state?.players ??
    draft.names.slice(0, draft.playerCount).map((name, index) => ({
      name,
      seed: index + 1,
    }));
  return JSON.stringify(
    {
      currentGame: state?.currentGame ? gameValue(state.currentGame) : null,
      currentMatch: state?.currentMatch ?? 0,
      currentRound: state?.currentRound ?? 0,
      currentTurn: state?.currentTurn ?? 0,
      format: TOURNAMENT_FORMAT,
      playerCount: state?.playerCount ?? draft.playerCount,
      players,
      rounds: state ? roundValues(state) : [],
      status: state?.status ?? 'setup',
      version: TOURNAMENT_VERSION,
    },
    null,
    2,
  );
}
import { isWon } from '../game.ts';
import { readTournamentGame } from './format-game-read.ts';
import { readPlayers, readRecordValues } from './format-record-read.ts';
import { TOURNAMENT_FORMAT, TOURNAMENT_MAX_BYTES, TOURNAMENT_VERSION } from './format.ts';
import type {
  PlayerCount,
  TournamentRound,
  TournamentState,
} from './model.ts';
import type { TournamentDraft } from './format.ts';
import {
  hasExactKeys,
  isJsonObject,
  isNonnegativeSafeInteger,
  isWithinBytes,
  parseJson,
} from '../saved-format.ts';

const ROOT_KEYS = [
  'currentGame',
  'currentMatch',
  'currentRound',
  'currentTurn',
  'format',
  'playerCount',
  'players',
  'rounds',
  'status',
  'version',
] as const;
export type TournamentLoad =
  | { readonly kind: 'setup'; readonly draft: TournamentDraft }
  | { readonly kind: 'tournament'; readonly state: TournamentState };

export function readTournamentText(text: string): TournamentLoad | null {
  const value = isWithinBytes(text, TOURNAMENT_MAX_BYTES) ? parseJson(text) : undefined;
  if (!isJsonObject(value) || !hasExactKeys(value, ROOT_KEYS)) return null;
  if (value.format !== TOURNAMENT_FORMAT || value.version !== TOURNAMENT_VERSION) return null;
  if (value.playerCount !== 4 && value.playerCount !== 8) return null;
  const count: PlayerCount = value.playerCount;
  if (value.status === 'setup') return readSetup(value, count);
  if (value.status !== 'playing' && value.status !== 'complete') return null;
  const record = readRecordValues(count, value.players, value.rounds, false);
  if (!record) return null;
  if (
    !isNonnegativeSafeInteger(value.currentRound) ||
    !isNonnegativeSafeInteger(value.currentMatch) ||
    (value.currentTurn !== 0 && value.currentTurn !== 1)
  )
    return null;
  const currentRound = value.currentRound;
  const currentMatch = value.currentMatch;
  const currentTurn: 0 | 1 = value.currentTurn;
  const status = value.status;
  const round = record.rounds[currentRound];
  const match = round?.matches[currentMatch];
  if (!round || !match || !validateProgress(record.rounds, currentRound, currentMatch)) return null;
  if (match.players[0] === null || match.players[1] === null) return null;
  const game = readTournamentGame(value.currentGame, match.boardCode);
  if (game === undefined || !validCurrentTurn(match.results, currentTurn, game)) return null;
  if (
    status === 'complete' &&
    (currentRound !== record.rounds.length - 1 ||
      currentMatch !== 0 ||
      currentTurn !== 1 ||
      !match.winnerSeed ||
      !game ||
      !isWon(game))
  )
    return null;
  return {
    kind: 'tournament',
    state: {
      ...record,
      currentGame: game,
      currentMatch,
      currentRound,
      currentTurn,
      status,
    },
  };
}

function readSetup(value: Record<string, unknown>, count: PlayerCount): TournamentLoad | null {
  const players = readPlayers(value.players, count, false);
  if (
    !players ||
    !Array.isArray(value.rounds) ||
    value.rounds.length !== 0 ||
    value.currentGame !== null ||
    value.currentRound !== 0 ||
    value.currentMatch !== 0 ||
    value.currentTurn !== 0
  )
    return null;
  return {
    kind: 'setup',
    draft: { playerCount: count, names: players.map((player) => player.name) },
  };
}

function validateProgress(
  rounds: readonly TournamentRound[],
  currentRound: number,
  currentMatch: number,
): boolean {
  return rounds.every((round, roundIndex) =>
    round.matches.every((match, matchIndex) => {
      const complete =
        match.winnerSeed !== null && match.results[0] !== null && match.results[1] !== null;
      const untouched =
        match.winnerSeed === null && match.results[0] === null && match.results[1] === null;
      if (roundIndex < currentRound) return complete;
      if (roundIndex > currentRound) return untouched;
      if (matchIndex < currentMatch) return complete;
      if (matchIndex > currentMatch) return untouched;
      return true;
    }),
  );
}

function validCurrentTurn(
  results: TournamentState['rounds'][number]['matches'][number]['results'],
  turn: 0 | 1,
  game: TournamentState['currentGame'],
): boolean {
  const result = results[turn];
  if (turn === 0 && results[1]) return false;
  if (turn === 1 && !results[0]) return false;
  if (!game) return result === null;
  const won = isWon(game);
  if (result === null) return !won;
  return won && result.moves === game.moves && Math.floor(result.elapsedMs) === game.elapsedMs;
}

import { ELAPSED_MAX_MS, MOVES_MAX } from '../game.ts';
import { parseBoardCode } from '../deck.ts';
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
import { openingPairings, roundName, roundSizes } from './bracket.ts';
import { winningSeed } from './rules.ts';
import type {
  MatchPlayers,
  MatchResult,
  MatchResults,
  PlayerCount,
  TournamentMatch,
  TournamentRound,
} from './model.ts';

const ROUND_KEYS = ['matches', 'name', 'size'] as const;
const MATCH_KEYS = ['boardCode', 'players', 'results', 'winnerSeed'] as const;
const RESULT_KEYS = ['elapsedMs', 'moves', 'playerSeed'] as const;

export function readRounds(
  value: unknown,
  count: PlayerCount,
  requireComplete: boolean,
): readonly TournamentRound[] | null {
  const sizes = roundSizes(count);
  if (!Array.isArray(value) || value.length !== sizes.length) return null;
  const usedCodes = new Set<string>();
  const rounds: TournamentRound[] = [];
  let previousWinners: readonly (number | null)[] = [];
  for (let roundIndex = 0; roundIndex < sizes.length; roundIndex += 1) {
    const size = sizes[roundIndex];
    const rawRound = value[roundIndex];
    const expectedCount = count / 2 ** (roundIndex + 1);
    if (
      !size ||
      !isJsonObject(rawRound) ||
      !hasExactKeys(rawRound, ROUND_KEYS) ||
      rawRound.name !== roundName(count, roundIndex) ||
      rawRound.size !== size ||
      !Array.isArray(rawRound.matches) ||
      rawRound.matches.length !== expectedCount
    )
      return null;
    const expectedPlayers =
      roundIndex === 0
        ? openingPairings(count)
        : Array.from({ length: expectedCount }, (_, index): MatchPlayers => [
            previousWinners[index * 2] ?? null,
            previousWinners[index * 2 + 1] ?? null,
          ]);
    const matches: TournamentMatch[] = [];
    for (let index = 0; index < expectedCount; index += 1) {
      const match = readMatch(
        rawRound.matches[index],
        expectedPlayers[index] ?? [null, null],
        size,
        usedCodes,
      );
      if (!match || (requireComplete && match.winnerSeed === null)) return null;
      matches.push(match);
    }
    rounds.push({ matches, name: roundName(count, roundIndex), size });
    previousWinners = matches.map((match) => match.winnerSeed);
  }
  return rounds;
}

function readMatch(
  value: unknown,
  expectedPlayers: MatchPlayers,
  size: number,
  usedCodes: Set<string>,
): TournamentMatch | null {
  if (!isJsonObject(value) || !hasExactKeys(value, MATCH_KEYS)) return null;
  if (typeof value.boardCode !== 'string' || parseBoardCode(value.boardCode)?.size !== size)
    return null;
  if (usedCodes.has(value.boardCode)) return null;
  usedCodes.add(value.boardCode);
  const players = readPlayers(value.players);
